def count_pairs(nums, target):
    num_freq = {}
    pair_count = 0

    for num in nums:
        complement = target - num
        if complement in num_freq:
            pair_count += num_freq[complement]

        if num in num_freq:
            num_freq[num] += 1
        else:
            num_freq[num] = 1

    return pair_count
